mapper.select:
SELECT SUM(price)
FROM trade_brokerage_record
WHERE user_id = #{userId}
  AND biz_type = #{bizType}
  AND status = #{status}
  AND unfreeze_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = FALSE

SELECT user_id AS id, SUM(price) AS brokeragePrice
FROM trade_brokerage_record
WHERE biz_type = #{bizType}
  AND status = #{status}
  AND deleted = FALSE
  AND unfreeze_time BETWEEN #{beginTime} AND #{endTime}
GROUP BY user_id
ORDER BY brokeragePrice DESC

SELECT COUNT(1)
FROM (
    SELECT user_id
    FROM trade_brokerage_record
    WHERE biz_type = #{bizType}
      AND status = #{status}
      AND deleted = FALSE
      AND unfreeze_time BETWEEN #{beginTime} AND #{endTime}
    GROUP BY user_id
    HAVING SUM(price) > #{brokeragePrice}
) t
